#include "MultiPreview.h"
#include <QApplication>

#include <objbase.h>
#include "DeckLinkAPI_i.c"

void displayHelp()
{
	printf("Usage: MultiPreview [-r/--rows <row count>] [-c/--columns <column count>] [-h/--help]\n\n");
	printf("Options:\n");
	printf("    -r/--rows <row count>           Number of preview rows (default = 2)\n");
	printf("    -c/--columns <column count>     Number of preview columns (default = 2)\n");
	printf("    -h/--help                       Help\n\n");
}

int main(int argc, char *argv[])
{
	QApplication a(argc, argv);

	HRESULT hr = ::CoInitialize(nullptr);
	if (!SUCCEEDED(hr))
		return hr;

	qRegisterMetaType<com_ptr<IDeckLinkVideoFrame>>("com_ptr<IDeckLinkVideoFrame>");

	QStringList args = QCoreApplication::arguments();

	int rows = 2;
	int columns = 2;

	for (int i = 1; i < args.size(); ++i)
	{
		QString arg = args.at(i);
		if ((arg == "-r" || arg == "--rows") && (i + 1 < argc))
		{
			rows = args.at(++i).toInt();
		}
		else if ((arg == "-c" || arg == "--columns") && (i + 1 < argc))
		{
			columns = args.at(++i).toInt();
		}
		else if  (arg == "-h" || arg == "--help")
		{
			displayHelp();
			return EXIT_SUCCESS;
		}
		else
		{
			displayHelp();
			return EXIT_FAILURE;
		}
	}

	MultiPreview w(rows, columns);

	int exitResult = a.exec();

	::CoUninitialize();

	return exitResult;
}
